messages.content:
{
  "anyOf": [
    {
      "type": "object",
      "properties": {
        "$jmespath": {
          "type": "string",
          "description": "A JMESPath expression."
        }
      },
      "required": [
        "$jmespath"
      ],
      "description": "A JMESPath expression which evaluates to a value."
    },
    {
      "type": "object",
      "properties": {
        "$starlark": {
          "type": "string",
          "description": "A Starlark expression."
        }
      },
      "required": [
        "$starlark"
      ],
      "description": "A Starlark expression which evaluates to a value."
    },
    {
      "type": "object",
      "properties": {
        "$special": {
          "enum": [
            "input",
            "output",
            "l1_normalized_function_output",
            "input_items_output_length",
            "input_items_optional_context_split",
            "input_items_optional_context_merge",
            "vector_completion_scores",
            "vector_completion_scores_weighted_sum"
          ],
          "description": "A predefined special expression variant."
        }
      },
      "required": [
        "$special"
      ],
      "description": "A special predefined expression."
    }
  ],
  "description": "An expression (JMESPath, Starlark, or Special) which evaluates to a value."
}

{
  "type": "object",
  "properties": {
    "type": {
      "const": "image_url"
    },
    "image_url": {
      "type": "object",
      "properties": {
        "url": {
          "type": "string",
          "description": "Either a URL of the image or the base64 encoded image data."
        },
        "detail": {
          "anyOf": [
            {
              "enum": [
                "auto",
                "low",
                "high"
              ],
              "description": "Specifies the detail level of the image."
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "required": [
        "url"
      ],
      "description": "The URL of the image and its optional detail level."
    }
  },
  "required": [
    "type",
    "image_url"
  ],
  "description": "An image rich content part."
}
